"""Offline integration of separately versioned supplementary diagnostics."""
from pathlib import Path
import hashlib
import json
import csv
import shutil

ROOT = Path(__file__).resolve().parents[1]
RUNS = ["20261003_044632Z_cba2c92c_openrouter_retry", "20261003_044847Z_ea685d74_openrouter_retry", "20261003_045116Z_54ff112b_openrouter_retry"]

def main():
    runs = [ROOT / "results" / name for name in RUNS]
    summaries = [json.loads((p / "summary.json").read_text(encoding="utf-8")) for p in runs]
    raw = [json.loads(line) for p in runs for line in (p / "raw.jsonl").read_text(encoding="utf-8").splitlines()]
    matrix = json.loads((runs[-1] / "catalogue_matrix.json").read_text(encoding="utf-8"))
    rows = []
    for row in matrix:
        measured = [a for a in raw if a["model_requested"] == row["resolved_model_id"]]
        status = "TESTED_OK" if measured and all(not a.get("error") for a in measured) else "TESTED_BLOCKED" if measured else "SKIPPED" if not row["eligible"] else "PRIVACY_BLOCKED_NOT_RUN" if row["privacy_eligibility"] == "EXCLUDED_FILTERED_CATALOG" else "NOT_RUN_BOUNDED_SCREEN"
        rows.append({"name": row["requested_display_name"], "id": row["resolved_model_id"], "found": "FOUND", "price_class": "FREE_CATALOGUE" if row["status"] != "PAID_NOT_AUTHORIZED" else "PAID", "modality": "/".join(row["modalities"].get("output_modalities", [])), "context_length": row["context_length"], "price_eligible": row["eligible"], "privacy_eligibility": row["privacy_eligibility"], "status": status, "http": "/".join(str(a["http_status"]) for a in measured), "attempts": len(measured), "successful": sum(a["http_status"] == 200 and not a.get("error") for a in measured), "provider": "/".join(sorted({a.get("provider_reported") or a["provider_pinned"] for a in measured})), "failure_reason": "; ".join(sorted({(a.get("raw") or {}).get("error", {}).get("message", a.get("error")) for a in measured if a.get("error")})) or (row["reason"] if not row["eligible"] else "filtered catalogue excludes model" if "PRIVACY_BLOCKED" in status else "bounded screen" if not measured else "")})
    out = ROOT / "results/openrouter_integrated_20261003"
    out.mkdir(exist_ok=True)
    with (out / "catalogue21.csv").open("w", encoding="utf-8-sig", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=list(rows[0])); writer.writeheader(); writer.writerows(rows)
    report = {"source_runs": RUNS, "found": len(rows), "tested_unique": sum(r["attempts"] > 0 for r in rows), "successful_unique": sum(r["successful"] > 0 for r in rows), "tested_blocked_unique": sum(r["status"] == "TESTED_BLOCKED" for r in rows), "privacy_blocked_not_run": sum(r["status"] == "PRIVACY_BLOCKED_NOT_RUN" for r in rows), "skipped": sum(r["status"] == "SKIPPED" for r in rows), "eligible_not_run": sum(r["status"] == "NOT_RUN_BOUNDED_SCREEN" for r in rows), "generation_attempts": len(raw), "successful_generations": sum(r["successful"] for r in rows), "external_requests": sum(s["total_external_requests"] for s in summaries), "shared_dev": [r for r in summaries[-1]["rows"] if r["attempts"]], "shared_dev_billed_usd": summaries[-1]["user_billed_cost_usd"], "diagnostic_failed_attempt_costs": "UNKNOWN individually; unchanged zero-cap key usage is zero; no invoice claim", "rows": rows}
    (out / "summary.json").write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    snapshot = runs[-1] / "runner_snapshot.py"
    shutil.copyfile(ROOT / "scripts/openrouter_retry_20261003.py", snapshot)
    hashes = {p.relative_to(ROOT).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest() for p in [snapshot, ROOT / "scripts/openrouter_screen_20261002.py", ROOT / "scripts/home_pc_benchmark.py", ROOT / "src/agro_route/models.py", ROOT / "src/agro_route/evaluation.py"]}
    (out / "provenance.json").write_text(json.dumps({"execution_source_shared_dev": hashes, "diagnostic_versions": "First two new diagnostics predate later CLI additions; exact request bodies retained, no execution-source snapshot captured then", "historical_results_changed": False, "raw_hashes": {p.name: hashlib.sha256((p / 'raw.jsonl').read_bytes()).hexdigest() for p in runs}}, indent=2), encoding="utf-8")
    lines = ["# OpenRouter после изменения приватности — 3 октября 2026", "", "**PARTIAL:** каталог и ограниченный DEV screen завершены; часть endpoints недоступна. Исторический Mercury/HOME150 не заменён. Никаких изменений аккаунта/ключей/лимитов/приватности runner не выполнял.", "", f"21/21 FOUND; {report['tested_unique']} разных моделей получили completion attempt, {report['successful_unique']} вернули генерацию. {report['tested_blocked_unique']} отдельных отказа, {report['privacy_blocked_not_run']} текстовых кандидатов исключены filtered catalogue, 3 SKIPPED (2 paid music, 1 classifier), {report['eligible_not_run']} eligible NOT RUN по ограниченному плану. Три новых run IDs: {', '.join(RUNS)}. Всего34 completion attempts,31 successful generations,183 внешних requests (149 metadata GETs); retries0.", "", "## Причины прежних и новых отказов", "", "- Старый401: `openrouter_api_key_2` остаётся management/provisioning; официальная документация исключает inference этим типом. Выбран уже существующий ordinary child того же аккаунта: limit0, include_byok_in_limit=true, usage0, expiry09.10; новый ключ не создавался.", "- Ling3.1 новый403: точное очищенное сообщение `Key limit exceeded (total limit)`. Это уточняет старый403, тело которого не было сохранено. При этом публичные model/endpoint token-price fields нулевые. Причина внутренней проверки/резерва стоимости alias сервисом не раскрыта; лимит не повышался.", "- СтарыйLFM404: одновременно Free model training и ZDR exclusions. Сейчас LFM отсутствует в authenticated `/models/user`, поэтому повторное inference NOT RUN. Точные значения переключателей account privacy API не раскрывает; нельзя утверждать, что все исключения сняты.", "- Apodex400: endpoint metadata заявляет structured_outputs, но provider body говорит json_schema unsupported, supported json_object. Параметры не менялись для повторного тюнинга; отдельная будущая совместимость допустима как новая DEV-версия.", "- Gemma26 429: provider identifies `upstream_provider_shared_pool`; не account-wide exhausted quota. Автоповторов, BYOK/paid fallback нет. Этот отказ не блокировал отдельно объявленный screen других доступных free моделей.", "", "[Management keys](https://openrouter.ai/docs/guides/overview/auth/management-api-keys), [provider price/pinning](https://openrouter.ai/docs/guides/routing/provider-selection), [ZDR](https://openrouter.ai/docs/guides/features/zdr), [filtered catalog](https://openrouter.ai/docs/api/api-reference/models/list-models-filtered-by-user-provider-preferences-privacy-settings-and-guardrails).", "", "## Общие девять DEV задач", "", "| Model | Correct/9 | Median seconds | Input/output tokens | Provider | Cost USD |", "|---|---:|---:|---:|---|---:|"]
    for r in report["shared_dev"]:
        lines.append(f"| {r['resolved_model_id']} | {r['correct']}/9 | {r['p50_latency_seconds']:.3f} | {r['known_input_tokens']['known_sum']}/{r['known_output_tokens']['known_sum']} | {', '.join(r['providers_reported'])} | 0 |")
    lines += ["", "27/27 HTTP200,27/27 exact JSON schema,27/27 reported cost0; key usage до/после0. Нулевая стоимость общего screen подтверждена API; отказавшие попытки имеют UNKNOWN individual usage/cost, не подставляются как измеренный0. Zero-cap/provider price guards соблюдены. Макс512tokens,temperature0,parallelism1; nonstream end-to-end latency, TTFT/backend TPS UNKNOWN. Remote version/quantization UNKNOWN.", "", "Это9 наблюдавшихся DEV задач с прежним strict exact scorer: ошибки QA-span и numeric могут снижать score без полной человеческой семантической оценки. Scorer v2 не использовался. Новые ответы не являются confirmatory holdout; качество по9 нельзя обобщать. Два успешных connectivity probes Ling не объединяются с9 для ranking. Qwen имеет лучшие наблюдаемые качество/latency из этой тройки, однако Pareto superiority на широком workload не установлена. Dots preview identity нестабильна. Численные/лексические source groups общие, независимая статистика здесь не рассчитывалась.", "", "## Все запрошенные модели", "", "| Display name / current ID | Status | Privacy | HTTP |", "|---|---|---|---|"]
    for r in rows:
        lines.append(f"| {r['name']} / `{r['id']}` | {r['status']} | {r['privacy_eligibility']} | {r['http'] or 'NOT RUN'} |")
    lines += ["", "Точные modalities,context,provider,prices,reason и числа попыток: [catalogue21.csv](../results/openrouter_integrated_20261003/catalogue21.csv), [summary](../results/openrouter_integrated_20261003/summary.json). Raw response/error metadata и request payloads сохраняются PRIVATE в трёх новых run folders; ключи и account key IDs очищены. Полная privacy модель не выводится из наличия модели в filtered catalog: доступность endpoint проверяется ответом. Первые два запуска диагностические; их отдельные code snapshots не были зафиксированы, ограничение записано в provenance. Shared DEV executed-source snapshot сохранён."]
    (ROOT / "docs/OPENROUTER_RETRY_20261003_RU.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(json.dumps({k: report[k] for k in ("found", "tested_unique", "successful_unique", "tested_blocked_unique", "privacy_blocked_not_run", "skipped", "eligible_not_run", "generation_attempts", "successful_generations", "external_requests")}))

if __name__ == "__main__":
    main()
